```python
class Gradebook:
    def __init__(self) -> None:
        # Map assignment name -> (weight, kind)
        self.assignments: dict[str, tuple[float, str]] = {}
        # Map student name -> dict of {assignment_name: grade}
        self.grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the allowed scale of 2.0 to 5.0.")
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self.grades.get(student, {})

        # Collect quizzes to evaluate if the lowest quiz grade needs to be dropped
        quizzes = []
        for name, (weight, kind) in self.assignments.items():
            if kind == "quiz":
                # Assignments without a recorded grade count as 2.0
                grade = student_grades.get(name, 2.0)
                quizzes.append((name, grade, weight))

        dropped_quiz_name = None
        if len(quizzes) > 1:
            # Identify the quiz with the lowest grade.
            # In case of ties, dropping any single lowest grade quiz is standard.
            dropped_quiz_name = min(quizzes, key=lambda q: q[1])[0]

        total_weighted_sum = 0.0
        total_weight = 0.0

        for name, (weight, kind) in self.assignments.items():
            if name == dropped_quiz_name:
                continue

            grade = student_grades.get(name, 2.0)
            total_weighted_sum += grade * weight
            total_weight += weight

        if total_weight == 0.0:
            return 0.0

        return round(total_weighted_sum / total_weight, 2)
```

