from collections import defaultdict
from typing import NamedTuple


class Assignment(NamedTuple):
    weight: float
    kind: str


class Gradebook:
    def __init__(self) -> None:
        self.assignments: dict[str, Assignment] = {}
        self.grades: dict[str, dict[str, float]] = defaultdict(dict)

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = Assignment(weight=weight, kind=kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the allowed scale of 2.0 to 5.0.")
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self.grades.get(student, {})

        # Identify all quizzes with their assigned or default grade
        quizzes = [
            (name, student_grades.get(name, 2.0))
            for name, meta in self.assignments.items()
            if meta.kind == "quiz"
        ]

        # Drop the lowest quiz if there is more than one
        dropped_quiz = min(quizzes, key=lambda q: q[1])[0] if len(quizzes) > 1 else None

        active_assignments = (
            (student_grades.get(name, 2.0), meta.weight)
            for name, meta in self.assignments.items()
            if name != dropped_quiz
        )

        total_weighted_sum = 0.0
        total_weight = 0.0
        for grade, weight in active_assignments:
            total_weighted_sum += grade * weight
            total_weight += weight

        if total_weight == 0.0:
            return 0.0

        return round(total_weighted_sum / total_weight, 2)
